324	<script>
325	  const ICONS = {
326	    grid: '<rect x="3" y="3" width="7" height="7" rx="1.6"/><rect x="14" y="3" width="7" height="7" rx="1.6"/><rect x="3" y="14" width="7" height="7" rx="1.6"/><rect x="14" y="14" width="7" height="7" rx="1.6"/>',
327	    server: '<rect x="3" y="4" width="18" height="6" rx="1.6"/><rect x="3" y="14" width="18" height="6" rx="1.6"/><circle cx="7" cy="7" r=".6" fill="currentColor" stroke="none"/><circle cx="7" cy="17" r=".6" fill="currentColor" stroke="none"/>',
328	    globe: '<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c2.8 2.6 4.2 5.7 4.2 9s-1.4 6.4-4.2 9c-2.8-2.6-4.2-5.7-4.2-9s1.4-6.4 4.2-9Z"/>',
329	    controller: '<rect x="3" y="8" width="18" height="10" rx="5"/><path d="M8 12h.01M8 15h.01M6.5 13.5h3M16 12h.01M17.5 13.5h.01"/>',
330	    stack: '<ellipse cx="12" cy="6" rx="8" ry="3"/><path d="M4 6v6c0 1.7 3.6 3 8 3s8-1.3 8-3V6M4 12v6c0 1.7 3.6 3 8 3s8-1.3 8-3v-6"/>',
331	    domain: '<circle cx="12" cy="12" r="9"/><path d="M12 3v18M3 12h18"/><path d="M6 6.5c1.6 1.4 3.7 2 6 2s4.4-.6 6-2M6 17.5c1.6-1.4 3.7-2 6-2s4.4.6 6 2"/>',
332	    mail: '<rect x="3" y="5" width="18" height="14" rx="2.4"/><path d="m4 7 8 6 8-6"/>',
333	    shield: '<path d="M12 3 5 6v5.5c0 4.4 3 7.7 7 9 4-1.3 7-4.6 7-9V6l-7-3Z"/><path d="m9.2 12 1.9 1.9L15 10"/>',
