396	  function drawHero(t){
397	    const w = canvas.width, h = canvas.height;
398	    ctx.clearRect(0,0,w,h);
399	    blobs.forEach(b => {
400	      const bx = (b.x + Math.sin(t * b.vx) * .08) * w;
401	      const by = (b.y + Math.cos(t * b.vy) * .08) * h;
402	      const g = ctx.createRadialGradient(bx,by,0,bx,by,b.r*w);
403	      g.addColorStop(0, b.c);
404	      g.addColorStop(1, 'transparent');
405	      ctx.fillStyle = g;
406	      ctx.fillRect(0,0,w,h);
407	    });
408	    if (!reduceMotion) requestAnimationFrame(drawHero);
409	  }
