246	  const fullBleed =
247	    pathname === "/dashboard/mail" || pathname === "/dashboard/calendar" || pathname === "/admin/inbox" || pathname === "/admin/board" || pathname === "/admin/reddit";
248	  // Wide (but still centered/padded, unlike fullBleed) routes — data-table-heavy
249	  // pages that were clipping real columns (Time on page/Account/Referrer) at
250	  // the standard 1280px cap. Keeps the page's own section padding/spacing
251	  // (fullBleed strips that entirely, which this page still relies on for its
