1	import type { HTMLAttributes, ReactNode } from "react";
2	import { IconArrowUp } from "./icons";
3	
4	/**
5	 * Shared surface/card/badge/gauge primitives for the portal v2 redesign.
6	 * These are genuinely new components — NOT the existing components/ui/
7	 * primitives.tsx (PageHeader/StatCard/Badge/EmptyState) restyled in place.
8	 * That file stays untouched and keeps serving the ~54 pages not yet
9	 * redesigned; this one is additive, for pages built against the new visual
10	 * system (scratchpad/portal-redesign-{shell,wizard,billing,server}.html).
11	 *
12	 * Dependency-free by design, matching this codebase's existing discipline
13	 * (ROADMAP.md: "dependency-free charts", no chart library) — <Gauge> and
14	 * <BarMeter> are hand-rolled SVG/CSS, same philosophy as
15	 * components/ui/charts.tsx's <Sparkline>/<AreaChart>. Reuse that existing
16	 * <Sparkline> as-is for line/area trends on redesigned pages — it has no
17	 * dependency on the old `.card` system, so there's nothing to port.
18	 */
19	
20	type Tone = "violet" | "cyan" | "green" | "blue";
21	type PillTone = "brand" | "good" | "warn" | "bad" | "neutral";
22	
23	/* ── Surface ──────────────────────────────────────────────────────────── */
24	
25	/**
26	 * Base panel/card surface (portal v2's answer to the old `.card`). Wraps the
27	 * `.pv-surface` / `.pv-surface-elevated` utility classes from globals.css so
28	 * plain markup and this component always stay pixel-identical.
29	 */
30	export function Surface({
31	  elevated = false,
32	  className = "",
33	  children,
34	  ...rest
35	}: HTMLAttributes<HTMLDivElement> & { elevated?: boolean }) {
36	  return (
37	    <div className={`${elevated ? "pv-surface-elevated" : "pv-surface"} ${className}`} {...rest}>
38	      {children}
39	    </div>
40	  );
41	}
42	
43	/* ── IconTile ─────────────────────────────────────────────────────────── */
44	
45	const ICON_TILE_TONES: Record<Tone, string> = {
46	  violet: "bg-pv-brand/[0.16] text-pv-brand-light",
47	  cyan: "bg-pv-cyan/[0.14] text-pv-cyan",
48	  green: "bg-pv-good/[0.14] text-pv-good",
49	  blue: "bg-pv-blue/[0.14] text-pv-blue",
50	};
51	
52	/** The colored icon square behind every stat-card icon (shell mockup's `.stat-icon`). */
53	export function IconTile({
54	  tone = "violet",
55	  size = 34,
56	  children,
57	}: {
58	  tone?: Tone;
59	  size?: number;
60	  children: ReactNode;
61	}) {
62	  return (
63	    <div
64	      className={`flex shrink-0 items-center justify-center rounded-pv-sm ${ICON_TILE_TONES[tone]}`}
65	      style={{ width: size, height: size }}
66	    >
67	      {children}
68	    </div>
69	  );
70	}
71	
72	/* ── Pill / StatusPill ────────────────────────────────────────────────── */
73	
74	const PILL_TONES: Record<PillTone, string> = {
75	  brand: "bg-pv-brand/20 text-pv-brand-light",
76	  good: "bg-pv-good/[0.15] text-pv-good",
77	  warn: "bg-pv-warn/[0.15] text-pv-warn",
78	  bad: "bg-pv-bad/[0.15] text-pv-bad",
79	  neutral: "bg-white/[0.08] text-pv-text-muted",
80	};
81	
82	/** Small static label pill — nav "NEW" tag, plan "Most popular" badge, term
83	 *  "Save 20%" callout. Not interactive; for a clickable variant, wrap it. */
84	export function Pill({ tone = "brand", children }: { tone?: PillTone; children: ReactNode }) {
85	  return (
86	    <span
87	      className={`inline-flex items-center rounded-full px-2 py-0.5 text-[10px] font-bold tracking-wide ${PILL_TONES[tone]}`}
88	    >
89	      {children}
90	    </span>
91	  );
92	}
93	
94	const STATUS_DOT_TONES: Record<PillTone, string> = {
95	  brand: "bg-pv-brand-light shadow-[0_0_6px_#a48bff]",
96	  good: "bg-pv-good shadow-[0_0_6px_#34d399]",
97	  warn: "bg-pv-warn shadow-[0_0_6px_#fbbf24]",
98	  bad: "bg-pv-bad shadow-[0_0_6px_#f87171]",
99	  neutral: "bg-pv-text-faint",
100	};
101	
102	/**
103	 * Status-dot-with-label pill (server-detail mockup's "● Running" chip). Unlike
104	 * components/ui/primitives.tsx's `StatusDot` (which maps raw enum status
105	 * strings like "RUNNING"/"SUSPENDED" to a color), this one takes an explicit
106	 * tone + label — the redesigned pages decide the mapping themselves, since
107	 * the new visual language uses a filled pill (not a bare dot + text).
108	 */
109	export function StatusPill({ tone = "good", children }: { tone?: PillTone; children: ReactNode }) {
110	  return (
111	    <span
112	      className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11.5px] font-bold ${PILL_TONES[tone]}`}
113	    >
114	      <span className={`h-1.5 w-1.5 shrink-0 rounded-full ${STATUS_DOT_TONES[tone]}`} />
115	      {children}
116	    </span>
117	  );
118	}
119	
120	/* ── StatCard ─────────────────────────────────────────────────────────── */
121	
122	export interface StatCardV2Props {
123	  label: string;
124	  value: ReactNode;
125	  icon?: ReactNode;
126	  tone?: Tone;
127	  /** Omit for no trend indicator (matches the shell mockup's "Uptime" stat, which has none). */
128	  trend?: { direction: "up" | "down"; label: string };
129	  className?: string;
130	}
131	
132	/** Portal v2 stat tile (shell mockup's `.stat-card`): icon tile + optional
133	 *  trend chip on top, big value, faint label below. */
134	export function StatCardV2({ label, value, icon, tone = "violet", trend, className = "" }: StatCardV2Props) {
135	  return (
136	    <Surface className={`p-[18px] ${className}`}>
137	      <div className="mb-3.5 flex items-center justify-between">
138	        {icon ? <IconTile tone={tone}>{icon}</IconTile> : <span />}
139	        {trend && (
140	          <span
141	            className={`flex items-center gap-0.5 text-[11px] font-bold ${
142	              trend.direction === "up" ? "text-pv-good" : "text-pv-bad"
143	            }`}
144	          >
145	            {trend.label}
146	            <IconArrowUp width={10} height={10} className={trend.direction === "down" ? "rotate-180" : ""} />
147	          </span>
148	        )}
149	      </div>
150	      <p className="mb-1 font-pv-display text-2xl font-bold leading-none text-pv-text">{value}</p>
151	      <p className="text-xs text-pv-text-faint">{label}</p>
152	    </Surface>
153	  );
154	}
155	
156	/* ── Gauge (semicircular, billing mockup) ────────────────────────────── */
157	
158	/**
159	 * Hand-rolled semicircular gauge — billing mockup's wallet-usage arc.
160	 * Geometry matches the mockup exactly: a 140x90 viewBox, radius-60 arc from
161	 * (10,80) to (130,80). That arc's true length is `π * r ≈ 188.5`, which is
162	 * where the mockup's hardcoded `stroke-dasharray="188"` came from — computed
163	 * here instead of hardcoded so `value` can be any 0-100, not just the
164	 * mockup's fixed 75%.
165	 */
166	export function Gauge({ value, size = 140 }: { value: number; size?: number }) {
167	  const pct = Math.max(0, Math.min(100, value));
168	  const height = size * (90 / 140);
169	  const arcLength = Math.PI * 60;
170	  const offset = arcLength * (1 - pct / 100);
171	  const gradientId = "pv-gauge-grad";
172	  return (
173	    <svg width={size} height={height} viewBox="0 0 140 90">
174	      <path d="M10 80 A60 60 0 0 1 130 80" fill="none" stroke="rgb(255 255 255 / 0.08)" strokeWidth="10" strokeLinecap="round" />
175	      <path
176	        d="M10 80 A60 60 0 0 1 130 80"
177	        fill="none"
178	        stroke={`url(#${gradientId})`}
179	        strokeWidth="10"
180	        strokeLinecap="round"
181	        strokeDasharray={arcLength}
182	        strokeDashoffset={offset}
183	        style={{ transition: "stroke-dashoffset 0.6s cubic-bezier(0.22,1,0.36,1)" }}
184	      />
185	      <defs>
186	        <linearGradient id={gradientId} x1="0" y1="0" x2="1" y2="0">
187	          <stop offset="0%" stopColor="#a48bff" />
188	          <stop offset="100%" stopColor="#22d3ee" />
189	        </linearGradient>
190	      </defs>
191	      <text
192	        x="70"
193	        y="72"
194	        textAnchor="middle"
195	        fill="#f4f5fb"
196	        fontFamily="var(--font-pv-display)"
197	        fontWeight={700}
198	        fontSize="18"
199	      >
200	        {Math.round(pct)}%
201	      </text>
202	    </svg>
203	  );
204	}
205	
206	/* ── BarMeter (linear, server-detail mockup) ─────────────────────────── */
207	
208	/**
209	 * Linear usage bar — server-detail mockup's CPU/Memory/Disk meters.
210	 * `tone="warn"` reproduces the mockup's disk-at-76%-amber-to-red treatment;
211	 * use it once a metric crosses whatever threshold the calling page defines
212	 * (the mockup didn't encode a fixed rule — it's a per-page call).
213	 */
214	export function BarMeter({
215	  value,
216	  max = 100,
217	  tone = "brand",
218	}: {
219	  value: number;
220	  max?: number;
221	  tone?: "brand" | "warn";
222	}) {
223	  const pct = Math.max(0, Math.min(100, (value / max) * 100));
224	  return (
225	    <div className="h-1.5 overflow-hidden rounded-full bg-white/[0.06]">
226	      <div
227	        className="h-full rounded-full"
228	        style={{
229	          width: `${pct}%`,
230	          background:
231	            tone === "warn"
232	              ? "linear-gradient(90deg, #fbbf24, #f87171)"
233	              : "linear-gradient(90deg, #a48bff, #22d3ee)",
234	          transition: "width 0.5s cubic-bezier(0.22,1,0.36,1)",
235	        }}
236	      />
237	    </div>
238	  );
239	}
