/** Shared helpers for presenting audit-log actions. Pure — safe in server and client components. */

const SCOPE_LABELS: Record<string, string> = {
  user: "Account",
  server: "Server",
  wallet: "Wallet",
  domain: "Domain",
  admin: "Admin",
};

export function humanizeAction(action: string): string {
  const dot = action.indexOf(".");
  if (dot === -1) return action.replace(/_/g, " ");
  const scope = action.slice(0, dot);
  const verb = action.slice(dot + 1).replace(/_/g, " ");
  return `${SCOPE_LABELS[scope] ?? scope[0]?.toUpperCase() + scope.slice(1)} · ${verb}`;
}

export function actionDotColor(action: string): string {
  if (action.includes("delete") || action.includes("suspend")) return "bg-red-400";
  if (action.startsWith("wallet") || action.includes("renew") || action.includes("topup")) return "bg-emerald-400";
  if (action.startsWith("domain")) return "bg-accent-cyan";
  if (action.startsWith("admin")) return "bg-amber-400";
  return "bg-brand-400";
}
