  /**
   * Is the mobile drawer currently a drawer at all? Below `lg` the rail is an
   * off-canvas panel translated out of view; at `lg` and up it is the ordinary
   * page sidebar and must never be hidden or inerted. Starts `true` (desktop)
   * so the server render and the first client render agree.
   */
  const [isDesktopRail, setIsDesktopRail] = useState(true);
  useEffect(() => {
    const mq = window.matchMedia("(min-width: 1024px)");
    const sync = () => setIsDesktopRail(mq.matches);
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);
  const drawerHidden = !isDesktopRail && !sidebarOpen;

  // Escape closes the drawer.
  useEffect(() => {
    if (!sidebarOpen) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setSidebarOpen(false);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [sidebarOpen]);

  // Navigating from a drawer link must close the drawer.
  useEffect(() => {
    setSidebarOpen(false);
  }, [pathname]);

  // Opening the bell marks everything read server-side; track the
  // optimistic-clear edge locally so the badge/bold titles clear immediately.
  const [notifMarked, setNotifMarked] = useState(false);
  useEffect(() => {
    setNotifMarked(false);
  }, [notifications]);
  const unread = notifMarked ? 0 : notifications.filter((n) => !n.readAt).length;

  // Live unread-INBOX count for the "Inbox" nav badge. Polled client-side
  // because IMAP is too slow to run on every layout render. Only polls when
  // the portal actually has a Mail entry; fails soft to no badge.
  const hasMailNav = nav.some((s) => s.items.some((i) => i.href === "/dashboard/mail"));
  const [mailUnread, setMailUnread] = useState(0);
  useEffect(() => {
    if (!hasMailNav) return;
    let alive = true;
    const load = () =>
      fetch("/api/mail/unread")
        .then((r) => (r.ok ? r.json() : { unread: 0 }))
        .then((d) => alive && setMailUnread(Number(d?.unread) || 0))
        .catch(() => {});
    load();
    const id = setInterval(load, 60_000);
    return () => {
      alive = false;
      clearInterval(id);
    };
  }, [hasMailNav]);

  // Live Matrix status for the "Matrix" nav tag.
  const hasMatrixNav = nav.some((s) => s.items.some((i) => i.href === "/dashboard/build"));
  const [matrixStatus, setMatrixStatus] = useState<{
    running: number;
    needsAttention: number;
    lastEventAt: string | null;
  }>({ running: 0, needsAttention: 0, lastEventAt: null });
  const [matrixSeenAt, setMatrixSeenAt] = useState<number>(0);
  useEffect(() => {
    try {
      const v = localStorage.getItem("nxeon.matrix.seenAt");
      if (v) {
        setMatrixSeenAt(Number(v) || 0);
      } else {
        const now = Date.now();
        setMatrixSeenAt(now);
        localStorage.setItem("nxeon.matrix.seenAt", String(now));
      }
    } catch {
      setMatrixSeenAt(Date.now());
    }
  }, []);
  useEffect(() => {
    if (!hasMatrixNav) return;
    let alive = true;
    const load = () =>
      fetch("/api/claude/console-status")
        .then((r) => (r.ok ? r.json() : null))
        .then((d) => {
          if (alive && d) {
            setMatrixStatus({
              running: Number(d.running) || 0,
              needsAttention: Number(d.needsAttention) || 0,
              lastEventAt: d.lastEventAt ?? null,
            });
          }
        })
        .catch(() => {});
    load();
    const id = setInterval(load, 20_000);
    return () => {
      alive = false;
      clearInterval(id);
    };
  }, [hasMatrixNav]);
  useEffect(() => {
    if (pathname !== "/dashboard/build") return;
    const now = Date.now();
    setMatrixSeenAt(now);
    try {
      localStorage.setItem("nxeon.matrix.seenAt", String(now));
    } catch {}
  }, [pathname, matrixStatus.lastEventAt]);
  const matrixTag: "running" | "update" | null =
    matrixStatus.running > 0
      ? "running"
      : matrixStatus.lastEventAt != null && Date.parse(matrixStatus.lastEventAt) > matrixSeenAt
        ? "update"
        : null;

  useEffect(() => {
    if (!notifOpen) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setNotifOpen(false);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [notifOpen]);

  // Flatten for the command palette: every sidebar entry, section-labeled.
  const flatNav = nav.flatMap((s) => s.items.map((i) => ({ label: i.label, href: i.href, section: s.label })));

  return (
    <TerminalDockProvider>
    <ComposeProvider>
    <MatrixProvider>
    <div className="flex min-h-screen bg-pv-bg text-pv-text">
      <CommandPalette nav={flatNav} />
      <FeedbackWidget />
      <VisitTracker kind="portal" />

      {/* Sidebar */}
      <aside
        id="portal-sidebar-v2"
        className={`fixed inset-y-0 left-0 z-40 flex w-64 flex-col border-r border-white/[0.07] bg-pv-surface-1 px-3.5 py-5 transition-all lg:sticky lg:top-0 lg:h-screen lg:translate-x-0 ${
          collapsed ? "lg:w-[4.75rem]" : "lg:w-64"
        } ${sidebarOpen ? "translate-x-0" : "-translate-x-full"}`}
        inert={drawerHidden}
        aria-hidden={drawerHidden || undefined}
      >
        <div className={`flex h-11 items-center px-1 pb-4 ${collapsed ? "lg:justify-center lg:px-0" : ""}`}>
          <Logo collapsed={collapsed} />
          <button
            type="button"
            className="btn-ghost ml-auto rounded-lg p-2 lg:hidden"
            aria-label="Close menu"
            onClick={() => setSidebarOpen(false)}
          >
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
              <path d="M6 6l12 12M18 6 6 18" />
            </svg>
          </button>
        </div>

        <nav className={`flex-1 space-y-4.5 overflow-y-auto pb-4 ${collapsed ? "lg:px-0" : ""}`}>
          {nav.map((section, si) => (
            <div key={si}>
              {section.label && (
                <p
                  className={`mb-2 px-2.5 text-[10.5px] font-bold uppercase tracking-[0.11em] text-pv-text-faint ${
                    collapsed ? "lg:hidden" : ""
                  }`}
                >
                  {section.label}
                </p>
              )}
              <div className="space-y-0.5">
                {section.items.map((item) => {
                  const active =
                    item.href === pathname || (item.href !== "/dashboard" && pathname.startsWith(item.href));
                  const badgeCount = item.href === "/dashboard/mail" && mailUnread > 0 ? mailUnread : item.badge;
                  const hasBadge = typeof badgeCount === "number" && badgeCount > 0;
                  const showMatrixTag = item.href === "/dashboard/build" && matrixTag !== null;
                  return (
                    <Link
                      key={item.href}
                      href={item.href}
                      onClick={() => setSidebarOpen(false)}
                      title={collapsed ? item.label : undefined}
                      className={`pv-nav-item ${active ? "pv-nav-item-active" : ""} ${
                        collapsed ? "lg:justify-center lg:px-2" : ""
                      }`}
                    >
                      <NavIcon name={item.icon} />
                      <span className={collapsed ? "lg:hidden" : ""}>{item.label}</span>
                      {showMatrixTag ? (
                        <span
                          className={`ml-auto rounded-full px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-wide ${
                            matrixTag === "running"
                              ? "animate-pulse bg-pv-warn/20 text-pv-warn"
                              : "bg-pv-good/20 text-pv-good"
                          } ${collapsed ? "lg:hidden" : ""}`}
                        >
                          {matrixTag === "running" ? "running" : "update"}
                        </span>
                      ) : item.tag ? (
                        <span
                          className={`ml-auto rounded-full bg-pv-good/[0.15] px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-wide text-pv-good ${
                            collapsed ? "lg:hidden" : ""
                          }`}
                        >
                          {item.tag}
                        </span>
                      ) : (
                        hasBadge && (
                          <span
                            className={`ml-auto flex h-[18px] min-w-[18px] items-center justify-center rounded-full px-1.5 text-[10px] font-semibold ${
                              active ? "bg-white/25 text-white" : "bg-pv-brand text-white"
                            } ${collapsed ? "lg:hidden" : ""}`}
                          >
                            {badgeCount! > 99 ? "99+" : badgeCount}
                          </span>
                        )
                      )}
                      {(hasBadge || showMatrixTag || item.tag) && (
                        <span
                          className={`absolute right-1.5 top-1.5 hidden h-2 w-2 rounded-full ring-2 ring-pv-surface-1 ${
                            showMatrixTag
                              ? matrixTag === "running"
                                ? "animate-pulse bg-pv-warn"
                                : "bg-pv-good"
                              : item.tag
                                ? "bg-pv-good"
                                : "bg-pv-brand"
                          } ${collapsed ? "lg:block" : ""}`}
                        />
                      )}
                    </Link>
                  );
                })}
              </div>
            </div>
          ))}
        </nav>

        <div className="border-t border-white/[0.07] pt-3">
          <div
            className={`relative overflow-hidden rounded-pv-md border border-white/[0.08] bg-gradient-to-br from-pv-brand/[0.10] via-pv-surface-1 to-pv-blue/[0.08] px-3 py-2.5 ${
              collapsed ? "lg:hidden" : ""
            }`}
          >
            <div className="pointer-events-none absolute -right-6 -top-8 h-16 w-16 rounded-full bg-pv-cyan/10 blur-2xl" />
            <div className="flex items-center gap-1.5 text-[10px] font-medium uppercase tracking-[0.08em] text-pv-text-muted">
              <IconWallet className="h-3 w-3 shrink-0 text-pv-brand-light" />
              Account Balance
            </div>
            <p className="mt-1 text-lg font-semibold tracking-tight text-pv-cyan drop-shadow-[0_0_14px_rgb(34_211_238_/_0.4)]">
              ${(user.balanceCents / 100).toFixed(2)}
            </p>
          </div>
          <p className={`mt-2 truncate px-1 text-xs text-pv-text-faint ${collapsed ? "lg:hidden" : ""}`}>
            {user.email}
          </p>
          <button
            onClick={toggleCollapsed}
            title={collapsed ? "Expand sidebar" : "Collapse sidebar"}
            className={`mt-2 hidden w-full items-center gap-2 rounded-lg px-2.5 py-2 text-xs font-medium text-pv-text-muted transition-colors hover:bg-white/[0.05] hover:text-pv-text lg:flex ${
              collapsed ? "lg:justify-center lg:px-0" : ""
            }`}
          >
            <svg
              width="16"
              height="16"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              className={`shrink-0 transition-transform ${collapsed ? "rotate-180" : ""}`}
            >
              <path d="M13 17l-5-5 5-5M20 17l-5-5 5-5" />
            </svg>
            <span className={collapsed ? "lg:hidden" : ""}>Collapse</span>
          </button>
        </div>
      </aside>
      {sidebarOpen && (
        <div className="fixed inset-0 z-30 bg-black/50 lg:hidden" onClick={() => setSidebarOpen(false)} />
      )}

      {/* Main */}
      <div className="flex min-w-0 flex-1 flex-col">
        {impersonation && (
          <div className="flex items-center justify-center gap-3 bg-gradient-to-r from-pv-warn/20 to-orange-500/20 px-4 py-2 text-sm text-amber-200">
            <span>
              Viewing as <b>{impersonation.targetEmail}</b> (impersonation active)
            </span>
            <button
              className="rounded-lg border border-amber-400/40 px-2.5 py-0.5 text-xs font-semibold hover:bg-amber-400/10"
              onClick={() => startTransition(() => stopImpersonating())}
            >
              Exit
            </button>
          </div>
        )}

        <header className="sticky top-0 z-20 flex h-16 items-center gap-3 border-b border-white/[0.07] bg-pv-bg/80 px-4 backdrop-blur-xl sm:px-6">
          <button
            type="button"
            className="btn-ghost rounded-lg p-2 lg:hidden"
            aria-label="Open menu"
            aria-expanded={sidebarOpen}
            aria-controls="portal-sidebar-v2"
            onClick={() => setSidebarOpen(true)}
          >
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M4 6h16M4 12h16M4 18h16" />
            </svg>
          </button>
          <button
            className="flex w-full max-w-sm items-center gap-2.5 rounded-pv-sm border border-white/[0.08] bg-white/[0.04] px-3.5 py-2 text-sm text-pv-text-faint transition-colors hover:border-white/20"
            onClick={() => {
              const ev = new KeyboardEvent("keydown", { key: "k", metaKey: true });
              window.dispatchEvent(ev);
            }}
          >
            <IconSearch className="h-[15px] w-[15px] shrink-0" />
            Search anything…
            <span className="kbd ml-auto">⌘K</span>
          </button>

          <div className="ml-auto flex items-center gap-2">
            <CurrencySwitcher />
            {user.role === "CUSTOMER" && (
              <Link
                href="/dashboard/refer"
                className="hidden items-center gap-1.5 rounded-full border border-pv-brand/30 bg-gradient-to-r from-pv-blue/15 to-pv-brand/15 px-3 py-1.5 text-xs font-semibold text-pv-brand-light transition-colors hover:border-pv-brand-light/50 hover:text-pv-text sm:inline-flex"
              >
                <IconShare className="h-3.5 w-3.5" />
                Refer &amp; earn
              </Link>
            )}
            {/* Notifications */}
            <div className="relative">
              <button
                className="btn-ghost relative rounded-xl p-2.5"
                aria-label={unread > 0 ? `Notifications, ${unread} unread` : "Notifications"}
                aria-expanded={notifOpen}
                onClick={() => {
                  setNotifOpen((v) => !v);
                  if (!notifOpen && unread > 0) {
                    setNotifMarked(true);
                    startTransition(() => markNotificationsRead());
                  }
                }}
              >
                <IconBell className="h-[18px] w-[18px]" />
                {unread > 0 && (
                  <span className="absolute -right-0.5 -top-0.5 flex h-4.5 min-w-[18px] items-center justify-center rounded-full bg-gradient-to-r from-pv-blue to-pv-brand px-1 text-[10px] font-bold text-white">
                    {unread}
                  </span>
                )}
              </button>
              {notifOpen && (
                <>
                  <button
                    type="button"
                    aria-label="Close notifications"
                    className="fixed inset-0 z-20 cursor-default"
                    onClick={() => setNotifOpen(false)}
                  />
                  <div className="absolute right-0 top-12 z-30 w-80 overflow-hidden rounded-pv-lg border border-white/15 bg-pv-surface-1 shadow-2xl shadow-black/50 ring-1 ring-black/20 animate-fade-up">
                    <p className="border-b border-white/10 bg-white/[0.03] px-4 py-3 text-sm font-semibold text-pv-text">
                      Notifications
                    </p>
                    <div className="max-h-80 overflow-y-auto">
                      {notifications.length === 0 ? (
                        <p className="px-4 py-8 text-center text-sm text-pv-text-faint">All caught up.</p>
                      ) : (
                        notifications.map((n) => {
                          const isUnread = !n.readAt && !notifMarked;
                          const inner = (
                            <div className="flex items-start gap-2">
                              {isUnread && (
                                <span className="mt-1.5 h-2 w-2 shrink-0 rounded-full bg-pv-brand-light" aria-hidden />
                              )}
                              <div className="min-w-0 flex-1">
                                <p className={`text-sm ${isUnread ? "font-semibold text-pv-text" : "text-pv-text-muted"}`}>
                                  {n.title}
                                </p>
                                {n.body && <p className="mt-0.5 text-xs text-pv-text-muted">{n.body}</p>}
                                <p className="mt-1 text-[11px] text-pv-text-faint">{new Date(n.createdAt).toLocaleString()}</p>
                              </div>
                            </div>
                          );
                          return n.href ? (
                            <Link
                              key={n.id}
                              href={n.href}
                              onClick={() => setNotifOpen(false)}
                              className="block border-b border-white/[0.07] px-4 py-3 transition-colors hover:bg-white/[0.06]"
                            >
                              {inner}
                            </Link>
                          ) : (
                            <div key={n.id} className="block border-b border-white/[0.07] px-4 py-3">
                              {inner}
                            </div>
                          );
                        })
                      )}
                    </div>
                  </div>
                </>
              )}
            </div>

            <DeployButton href="/dashboard/deploy" className="hidden sm:inline-flex">
              Deploy
            </DeployButton>

            {/* User */}
            <div className="flex items-center gap-3 rounded-pv-sm border border-white/[0.08] bg-white/[0.03] py-1.5 pl-3 pr-2">
              <div className="hidden text-right sm:block">
                <p className="text-[13px] font-semibold leading-tight">{user.name}</p>
                <p className="text-[11px] leading-tight text-pv-text-faint">{user.email}</p>
              </div>
              <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-gradient-to-br from-pv-blue to-pv-brand text-sm font-bold">
                {user.name.charAt(0).toUpperCase()}
              </div>
              <form action={logout}>
                <button className="btn-ghost rounded-lg p-1.5" title="Sign out">
                  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                    <path d="M9 21H5a2 2 0 01-2-2V5a2 2 0 012-2h4M16 17l5-5-5-5M21 12H9" />
                  </svg>
                </button>
              </form>
            </div>
          </div>
        </header>

        {fullBleed ? (
          <main className="min-h-0 flex-1 overflow-hidden">{children}</main>
        ) : (
          <main className="mx-auto w-full max-w-7xl flex-1 px-4 py-8 sm:px-6 animate-fade-up">{children}</main>
        )}
      </div>
    </div>
    </MatrixProvider>
    </ComposeProvider>
    </TerminalDockProvider>
  );
}

