// Portal v2 nav: intent-based groups (Overview / Infrastructure / Grow / Build
// / Account) per the approved shell mockup (scratchpad/portal-redesign-shell.html),
// replacing the old reactively-merged 7-section layout. Every href below is
// unchanged from the old nav — only the grouping and icon keys changed. Icon
// keys are looked up in components/portal-v2/DashboardShellV2.tsx's NAV_ICONS
// map. Moves worth calling out for review:
//   - Migration Center moved from "Tools" into Infrastructure (it deploys/
//     migrates infra, same intent as Deploy/Servers).
//   - Partner Program moved from "Account" into Grow, alongside the other
//     growth-channel item Refer & earn (both are "grow your account" plays,
//     not account administration).
//   - Free tools moved from "Tools" into Build (utility/dev tooling).
//   - What's New moved from "Tools" into Account (product-update feed reads
//     closer to account-level notices than to Build's dev tooling).
//   - Website builder + Calendar (old "Network" section) folded into Grow
//     alongside Domains/SSL, matching how the mockup's Grow group absorbs the
//     old Network + Mail + Refer&earn sections.
//   - Inbox + Mailboxes (old "Mail" section) also folded into Grow for the
//     same reason; kept adjacent as before.
// No "NEW" tag on Refer & earn: the approved mockup shows one, but nothing in
// the real data model marks it as new, so adding it here would be a
// fabricated badge — left off per the no-invented-content constraint.
const nav: NavSection[] = [
  {
    items: [{ label: "Dashboard", href: "/dashboard", icon: "overview" }],
  },
  {
    label: "Infrastructure",
    items: [
      { label: "Deploy", href: "/dashboard/deploy", icon: "plus" },
      { label: "Servers", href: "/dashboard/servers", icon: "servers" },
      { label: "Shared Hosting", href: "/dashboard/hosting", icon: "globe" },
      { label: "Game Servers", href: "/dashboard/games", icon: "controller", tag: "FREE" },
      { label: "Server Directory", href: "/game-servers/directory", icon: "globe" },
      { label: "Volumes", href: "/dashboard/volumes", icon: "stack" },
      { label: "Migration Center", href: "/dashboard/migrate", icon: "rocket" },
    ],
  },
  {
    label: "Grow",
    items: [
      { label: "Domains", href: "/dashboard/domains", icon: "domain" },
      { label: "Website builder", href: "/dashboard/sites", icon: "globe" },
      { label: "Calendar", href: "/dashboard/calendar", icon: "calendar" },
