import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { AutoRefresh } from "@/components/AutoRefresh";
import { StatusDot, Badge, fmtMoney, timeAgo } from "@/components/ui/primitives";
import { DeployButton } from "@/components/customer/DeployButton";
import { humanizeAction, actionDotColor } from "@/components/customer/humanize";
import OnboardingChecklist from "@/components/customer/OnboardingChecklist";
import { getOnboardingSteps } from "@/lib/actions-onboarding";
import { renewalCharge } from "@/lib/renewal-charge";
import { dedicatedIpMonthlyCents } from "@/lib/dedicated-ip";
import { annualDiscountPct } from "@/lib/annual-discount";
import { taxContextForUser } from "@/lib/tax";
import { DEFAULT_ANNUAL_DISCOUNT_PCT } from "@/lib/billing-terms";
import { extraDiskPerGbCents } from "@/lib/disk-expand";
import { backupPlusMonthlyCents } from "@/lib/backup-upgrade";
import { Surface, StatCardV2 } from "@/components/portal-v2/primitives";
import {
  IconServers,
  IconPulse,
  IconChart,
  IconWallet,
  IconPlus,
  IconDomain,
  IconHeadset,
  IconChevron,
} from "@/components/portal-v2/icons";

export const dynamic = "force-dynamic";

export default async function DashboardPage() {
  const user = await requireUser();
  const [servers, auditLogs, transactions] = await Promise.all([
    db.server.findMany({
      where: { userId: user.id },
      // `gamePlan` and `dedicatedIp` are what `renewalCharge` needs; without
      // them the spend tile could only reach for `plan.priceCents`, which is a
      // different number for both.
      include: { plan: true, osTemplate: true, gamePlan: true, dedicatedIp: true },
      orderBy: { createdAt: "desc" },
    }),
    db.auditLog.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
      take: 8,
    }),
    db.walletTransaction.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
      take: 5,
    }),
  ]);

  const running = servers.filter((s) => s.status === "RUNNING").length;

  // "Monthly spend" is priced through `renewalCharge` — the single function
  // worker/billing.ts, the saved-card path and the "Renew now" button all charge
  // through (lib/renewal-charge.ts). It used to sum `plan.priceCents`, which is a
  // SECOND formula and a different number: it billed a $4.99 game server at
  // its $8.99 base VPS plan, and counted nothing at all for purchased extra disk
  // or a dedicated IP that the customer really does pay for every cycle.
  const paid = servers.filter((s) => !s.isFree && s.status !== "DELETING");
  // VAT/GST for this customer (Finding 1), so the "Monthly spend" figure is
  // tax-inclusive and matches what actually gets charged.
  const spendTaxRatePercent = (await taxContextForUser(user)).ratePercent;
  const spendPrices =
    paid.length > 0
      ? {
          ipMonthlyCents: await dedicatedIpMonthlyCents(),
          extraDiskPerGbCents: await extraDiskPerGbCents(),
          backupPlusCents: await backupPlusMonthlyCents(),
          annualDiscountPct: await annualDiscountPct(),
          taxRatePercent: spendTaxRatePercent,
        }
      // No paid servers -> renewalCharge is never called; the shipped default just
      // satisfies the required field.
      : { ipMonthlyCents: 0, extraDiskPerGbCents: 0, backupPlusCents: 0, annualDiscountPct: DEFAULT_ANNUAL_DISCOUNT_PCT, taxRatePercent: spendTaxRatePercent };
  // A term total divided by the months it buys — a presentation of the
  // authoritative figure, never a re-derivation of it.
  const monthlySpendCents = paid.reduce((sum, s) => {
    const charge = renewalCharge(s, spendPrices);
    return sum + Math.round(charge.totalCents / Math.max(1, charge.months));
  }, 0);
  const transitional = servers.some((s) =>
    ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)
  );

  const firstName = user.name.split(" ")[0];

  return (
    <div className="space-y-6">
      <OnboardingChecklist steps={await getOnboardingSteps()} />
      {transitional && <AutoRefresh />}

      {/* Ambient hero — portal v2 shell mockup's welcome band. `.pv-ambient`
          paints the drifting gradient-mesh background (pure CSS, respects
          prefers-reduced-motion); no fabricated stats in the copy, only real
          counts already computed above. */}
      <div className="pv-ambient overflow-hidden rounded-pv-xl border border-white/[0.07] bg-pv-surface-1 p-7 sm:p-9">
        <div className="flex flex-wrap items-center justify-between gap-6">
          <div>
            <h1 className="font-pv-display text-2xl font-bold sm:text-[26px]">
              Welcome back,{" "}
              <span className="bg-gradient-to-r from-pv-brand-light to-pv-cyan bg-clip-text text-transparent">
                {firstName}
              </span>
            </h1>
            <p className="mt-1.5 max-w-[46ch] text-[13.5px] leading-relaxed text-pv-text-muted">
              {servers.length === 0
                ? "No servers deployed yet — spin up your first one in under two minutes."
                : `${running} of ${servers.length} server${servers.length === 1 ? "" : "s"} running right now.`}
            </p>
          </div>
          <div className="flex flex-wrap gap-2.5">
            <Link
              href="/dashboard/billing"
              className="inline-flex items-center gap-1.5 rounded-pv-sm border border-white/[0.14] bg-white/[0.05] px-4 py-2.5 text-[13px] font-semibold text-pv-text"
            >
              <IconWallet width={15} height={15} />
              Add funds
            </Link>
            <DeployButton href="/dashboard/deploy">Deploy a server</DeployButton>
          </div>
        </div>
      </div>

      {servers.length === 0 ? (
        <Surface className="pv-ambient relative overflow-hidden py-16 text-center">
          <div className="relative">
            <div className="mx-auto mb-5 w-fit rounded-pv-lg border border-white/[0.08] bg-gradient-to-br from-pv-blue/20 to-pv-brand/20 p-5 text-pv-brand-light">
              <svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.4">
                <path d="M4.5 16.5 3 21l4.5-1.5M14.5 4.5c2.5-2.5 6-2.5 6-2.5s0 3.5-2.5 6L10 16l-3.5.5L6 13l8.5-8.5Z" />
                <path d="M9 15 6 12" />
                <circle cx="15" cy="9" r="1.2" />
              </svg>
            </div>
            <h2 className="font-pv-display text-xl font-bold">
              Launch your first{" "}
              <span className="bg-gradient-to-r from-pv-brand-light to-pv-cyan bg-clip-text text-transparent">
                VPS
              </span>
            </h2>
            <p className="mx-auto mt-2 max-w-md text-sm text-pv-text-muted">
              NVMe-backed KVM servers on a dedicated hypervisor, provisioned in under two minutes.
              Pick a plan, choose an OS, and you&apos;re live.
            </p>
            <Link href="/dashboard/deploy" className="btn-primary mt-6 inline-flex px-8">
              Deploy your first server
            </Link>
          </div>
        </Surface>
      ) : (
        <>
          <div className="grid gap-3.5 sm:grid-cols-2 xl:grid-cols-4">
            <Link href="/dashboard/servers">
              <StatCardV2 label="Total servers" value={String(servers.length)} icon={<IconServers />} tone="violet" />
            </Link>
            <Link href="/dashboard/servers">
              <StatCardV2 label="Running" value={`${running} / ${servers.length}`} icon={<IconPulse />} tone="green" />
            </Link>
            <Link href="/dashboard/billing">
              <StatCardV2 label="Monthly spend" value={fmtMoney(monthlySpendCents)} icon={<IconChart />} tone="blue" />
            </Link>
            <Link href="/dashboard/billing">
              <StatCardV2 label="Wallet balance" value={fmtMoney(user.balanceCents)} icon={<IconWallet />} tone="cyan" />
            </Link>
          </div>

          <Surface className="overflow-x-auto p-0">
            <div className="flex items-center justify-between px-4.5 pt-4.5">
              <p className="text-[11px] font-bold uppercase tracking-[0.09em] text-pv-text-faint">Servers</p>
              <Link href="/dashboard/servers" className="text-xs font-semibold text-pv-brand-light hover:underline">
                View all →
              </Link>
            </div>
            <table className="table-shell mt-2 min-w-[680px]">
              <thead>
                <tr>
                  <th>Hostname</th>
                  <th>Status</th>
                  <th>Plan</th>
                  <th>Access</th>
                  <th className="text-right">Actions</th>
                </tr>
              </thead>
              <tbody>
                {servers.map((s) => (
                  <tr key={s.id}>
                    <td>
                      <Link
                        href={`/dashboard/servers/${s.id}`}
                        className="font-semibold text-pv-text hover:text-pv-brand-light"
                      >
                        {s.hostname}
                      </Link>
                      {s.isFree && (
                        <span className="ml-2 align-middle">
                          <Badge tone="brand">free</Badge>
                        </span>
                      )}
                    </td>
                    <td>
                      <StatusDot status={s.status} />
                    </td>
                    <td className="text-pv-text-muted">
                      {s.plan.name} · {s.plan.cpuCores} vCPU · {s.plan.ramMB / 1024} GB
                    </td>
                    <td className="font-mono text-xs text-pv-text-muted">
                      {s.sshPort ? `${process.env.PUBLIC_IP}:${s.sshPort}` : "—"}
                    </td>
                    <td className="text-right">
                      <Link href={`/dashboard/servers/${s.id}`} className="btn-secondary px-3 py-1 text-xs">
                        Manage
                      </Link>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            <div className="h-1" />
          </Surface>

          {/*
            `grid-cols-1` is not cosmetic. Without an explicit base template this
            grid has no `grid-template-columns` under `lg`, so the browser creates
            an IMPLICIT `auto` track — and an implicit auto track is sized
            min-content, which the container cannot clamp. `grid-cols-1` compiles
            to `repeat(1, minmax(0, 1fr))` — the same `minmax(0, …)` that
            `lg:grid-cols-[1.6fr_1fr]` already uses, which is exactly why the
            desktop layout never had this problem. Ratio matches the shell
            mockup's activity/quick-actions two-column split.
          */}
          <div className="grid grid-cols-1 gap-4 lg:grid-cols-[1.6fr_1fr]">
            <div className="space-y-4">
              <Surface className="p-5">
                <div className="mb-3.5 flex items-center justify-between">
                  <p className="font-pv-display text-[15px] font-bold">Recent activity</p>
                  <Link href="/dashboard/activity" className="text-xs font-semibold text-pv-brand-light hover:underline">
                    Full log →
                  </Link>
                </div>
                {auditLogs.length === 0 ? (
                  <p className="text-sm text-pv-text-muted">No activity yet.</p>
                ) : (
                  <ul>
                    {auditLogs.map((log, i) => (
                      <li
                        key={log.id}
                        className={`flex items-center gap-3 py-2.5 text-sm ${
                          i < auditLogs.length - 1 ? "border-b border-white/[0.06]" : ""
                        }`}
                      >
                        <span className={`h-2 w-2 shrink-0 rounded-full ${actionDotColor(log.action)}`} />
                        <div className="min-w-0 flex-1">
                          <p className="text-pv-text">{humanizeAction(log.action)}</p>
                          {log.detail && <p className="truncate text-xs text-pv-text-faint">{log.detail}</p>}
                        </div>
                        <span className="shrink-0 text-[11.5px] text-pv-text-faint">{timeAgo(log.createdAt)}</span>
                      </li>
                    ))}
                  </ul>
                )}
              </Surface>

              <Surface className="p-5">
                <div className="mb-3.5 flex items-center justify-between">
                  <p className="font-pv-display text-[15px] font-bold">Recent transactions</p>
                  <Link href="/dashboard/billing" className="text-xs font-semibold text-pv-brand-light hover:underline">
                    Billing →
                  </Link>
                </div>
                {transactions.length === 0 ? (
                  <p className="text-sm text-pv-text-muted">No transactions yet.</p>
                ) : (
                  <ul>
                    {transactions.map((t, i) => (
                      <li
                        key={t.id}
                        className={`flex items-center gap-3 py-2.5 text-sm ${
                          i < transactions.length - 1 ? "border-b border-white/[0.06]" : ""
                        }`}
                      >
                        <span className="min-w-0 flex-1 truncate text-pv-text">{t.description}</span>
                        <span
                          className={`shrink-0 font-mono text-xs ${
                            t.amountCents < 0 ? "text-pv-bad" : "text-pv-good"
                          }`}
                        >
                          {t.amountCents < 0 ? "−" : "+"}
                          {fmtMoney(Math.abs(t.amountCents))}
                        </span>
                        <span className="shrink-0 text-[11.5px] text-pv-text-faint">{timeAgo(t.createdAt)}</span>
                      </li>
                    ))}
                  </ul>
                )}
              </Surface>
            </div>

            <Surface className="h-fit p-5">
              <p className="mb-3.5 font-pv-display text-[15px] font-bold">Quick actions</p>
              <div className="space-y-2">
                <Link
                  href="/dashboard/deploy"
                  className="flex items-center gap-2.5 rounded-pv-md border border-white/[0.07] px-3 py-2.5 text-[12.5px] font-semibold text-pv-text transition-colors hover:border-white/[0.14] hover:bg-white/[0.02]"
                >
                  <IconPlus width={16} height={16} className="shrink-0 text-pv-brand-light" />
                  <span className="flex-1">Deploy a new server</span>
                  <IconChevron width={14} height={14} className="shrink-0 text-pv-text-faint" />
                </Link>
                <Link
                  href="/dashboard/domains"
                  className="flex items-center gap-2.5 rounded-pv-md border border-white/[0.07] px-3 py-2.5 text-[12.5px] font-semibold text-pv-text transition-colors hover:border-white/[0.14] hover:bg-white/[0.02]"
                >
                  <IconDomain width={16} height={16} className="shrink-0 text-pv-brand-light" />
                  <span className="flex-1">Register a domain</span>
                  <IconChevron width={14} height={14} className="shrink-0 text-pv-text-faint" />
                </Link>
                <Link
                  href="/dashboard/support"
                  className="flex items-center gap-2.5 rounded-pv-md border border-white/[0.07] px-3 py-2.5 text-[12.5px] font-semibold text-pv-text transition-colors hover:border-white/[0.14] hover:bg-white/[0.02]"
                >
                  <IconHeadset width={16} height={16} className="shrink-0 text-pv-brand-light" />
                  <span className="flex-1">Contact support</span>
                  <IconChevron width={14} height={14} className="shrink-0 text-pv-text-faint" />
                </Link>
              </div>

              <div className="mt-3.5 rounded-pv-md border border-pv-brand-light/25 bg-gradient-to-br from-pv-brand/[0.14] to-pv-cyan/[0.05] p-4">
                <p className="text-[11px] text-pv-text-muted">Wallet balance</p>
                <p className="mt-1 mb-2.5 font-pv-display text-xl font-bold">{fmtMoney(user.balanceCents)}</p>
                <Link
                  href="/dashboard/billing"
                  className="block w-full rounded-lg border border-white/[0.14] bg-white/[0.08] py-2 text-center text-xs font-semibold text-pv-text"
                >
                  Add funds
                </Link>
              </div>
            </Surface>
          </div>
        </>
      )}
    </div>
  );
}

